<?php
require_once __DIR__.'/../includes/bootstrap.php';
if(empty($_SESSION['reset_customer_id']) || empty($_SESSION['reset_verified'])) redirect('/auth/forgot-password.php');
$title='Reset Password';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
  check_csrf();$pass=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm_password']??'');
  $s=$pdo->prepare('SELECT * FROM password_reset_otps WHERE reset_id=? AND customer_id=? LIMIT 1');$s->execute([(int)$_SESSION['reset_verified'],(int)$_SESSION['reset_customer_id']]);$r=$s->fetch();
  if(!$r || empty($r['verified_at']) || strtotime($r['expires_at'])<time()) $errors[]='Your verification session has expired. Please start again.';
  if(strlen($pass)<8)$errors[]='New password must be at least 8 characters.'; if($pass!==$confirm)$errors[]='Passwords do not match.';
  if(!$errors){$pdo->prepare('UPDATE customers SET password_hash=? WHERE customer_id=?')->execute([password_hash($pass,PASSWORD_DEFAULT),(int)$_SESSION['reset_customer_id']]);$pdo->prepare('DELETE FROM password_reset_otps WHERE customer_id=?')->execute([(int)$_SESSION['reset_customer_id']]);unset($_SESSION['reset_customer_id'],$_SESSION['reset_lookup'],$_SESSION['reset_expires'],$_SESSION['reset_verified']);$_SESSION['flash']=['type'=>'success','msg'=>'Your password has been reset successfully. Please sign in with your new password.'];redirect('/auth/customer-login.php');}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><link rel="stylesheet" href="/assets/style.css?v=22"></head><body class="auth-body"><script>function shadrilGoBack(){try{if(document.referrer){var u=new URL(document.referrer,location.href);if(u.origin===location.origin){history.back();return false;}}}catch(e){}location.href="/";return false;}</script><div class="auth-wrap"><a class="brand auth-brand" href="/">Shadril Shopping Store</a><div class="auth-page-back"><?=back_button('Previous page')?></div><div class="auth-card auth-special"><div class="auth-icon">🔑</div><div class="auth-copy"><span class="eyebrow">NEW PASSWORD</span><h1>Reset your password</h1><p>Create a new password for your Shadril customer account.</p></div><?php if($errors): ?><div class="errors"><?=e($errors[0])?></div><?php endif; ?><form method="post" class="form"><?=csrf_field()?><label>New password<input type="password" name="password" minlength="8" required autocomplete="new-password"></label><label>Confirm new password<input type="password" name="confirm_password" minlength="8" required autocomplete="new-password"></label><button class="btn primary full">Save new password</button></form></div></div></body></html>
